<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  :root{
    --bg:#0d1117;
    --panel:#161b22;
    --accent:#3fb950;
    --food:#f85149;
    --grid:#21262d;
    --text:#c9d1d9;
  }
  html,body{
    height:100%;
    margin:0;
    background:var(--bg);
    color:var(--text);
    font-family:'Segoe UI', Arial, sans-serif;
    display:flex;
    align-items:center;
    justify-content:center;
  }
  .wrap{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:14px;
    padding:20px;
  }
  h1{
    margin:0;
    font-size:28px;
    letter-spacing:2px;
    color:var(--accent);
    text-shadow:0 0 8px rgba(63,185,80,0.5);
  }
  #board-container{
    padding:10px;
    background:var(--panel);
    border-radius:12px;
    box-shadow:0 0 20px rgba(0,0,0,0.6);
  }
  canvas#snake{
    display:block;
    background:#010409;
    border-radius:6px;
    image-rendering:pixelated;
  }
  .controls{
    display:flex;
    gap:10px;
    align-items:center;
  }
  button{
    background:var(--accent);
    color:#0d1117;
    border:none;
    padding:8px 18px;
    border-radius:6px;
    font-weight:bold;
    font-size:14px;
    cursor:pointer;
    transition:transform 0.1s ease, opacity 0.2s;
  }
  button:hover{
    transform:translateY(-1px);
    opacity:0.9;
  }
  button:active{
    transform:translateY(1px);
  }
  #pause{ background:#d29922; }
  #reset{ background:#f85149; }
  .score-box{
    font-size:18px;
    background:var(--panel);
    padding:8px 16px;
    border-radius:8px;
    min-width:140px;
    text-align:center;
  }
  #score{
    font-weight:bold;
    color:var(--accent);
  }
  .status{
    font-size:13px;
    color:#8b949e;
    min-height:18px;
  }
</style>
